import java.util.Arrays;

abstract class SortAlgorithm<T extends Comparable<T>> {
    // Template method - defines skeleton, calls compare() and swap()
    public abstract void sort(T[] array);

    // Compare two elements: return true if a should come after b
    protected abstract boolean compare(T a, T b);

    // Swap elements at indices i and j
    protected abstract void swap(T[] array, int i, int j);
}

class BubbleSort<T extends Comparable<T>> extends SortAlgorithm<T> {
    @Override
    protected boolean compare(T a, T b) {
        return a.compareTo(b) > 0; // true if a > b -> need swap for ascending
    }

    @Override
    protected void swap(T[] array, int i, int j) {
        T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    @Override
    public void sort(T[] array) {
        int n = array.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (compare(array[j], array[j + 1])) {
                    swap(array, j, j + 1);
                }
            }
        }
    }
}

class SelectionSort<T extends Comparable<T>> extends SortAlgorithm<T> {
    @Override
    protected boolean compare(T a, T b) {
        return a.compareTo(b) < 0; // true if a < b -> a is new minimum
    }

    @Override
    protected void swap(T[] array, int i, int j) {
        T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    @Override
    public void sort(T[] array) {
        int n = array.length;
        for (int i = 0; i < n - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < n; j++) {
                if (compare(array[j], array[minIdx])) {
                    minIdx = j;
                }
            }
            if (minIdx != i) {
                swap(array, i, minIdx);
            }
        }
    }
}

public class Main {
    public static void main(String[] args) {
        SortAlgorithm<Integer> bubbleInt = new BubbleSort<>();
        SortAlgorithm<Integer> selectionInt = new SelectionSort<>();
        SortAlgorithm<String> bubbleStr = new BubbleSort<>();
        SortAlgorithm<String> selectionStr = new SelectionSort<>();

        Integer[] arr1 = {64, 34, 25, 12, 22, 11, 90};
        Integer[] arr2 = arr1.clone();
        System.out.println("Original Integers: " + Arrays.toString(arr1));

        bubbleInt.sort(arr1);
        System.out.println("BubbleSort Integers: " + Arrays.toString(arr1));

        selectionInt.sort(arr2);
        System.out.println("SelectionSort Integers: " + Arrays.toString(arr2));

        String[] arr3 = {"banana", "apple", "cherry", "mango"};
        String[] arr4 = arr3.clone();
        System.out.println("\nOriginal Strings: " + Arrays.toString(arr3));

        bubbleStr.sort(arr3);
        System.out.println("BubbleSort Strings: " + Arrays.toString(arr3));

        selectionStr.sort(arr4);
        System.out.println("SelectionSort Strings: " + Arrays.toString(arr4));
    }
}
